// Registry
const SHIP_ASSETS: Record<string, ShipSVGData> = {
  AX15: { hull: AX15_HULL, flames: AX15_FLAMES },
  KARQQ: { hull: KARQQ_HULL, flames: KARQQ_FLAMES },
  SCORJ: { hull: SCORJ_HULL, flames: SCORJ_FLAMES },
  STNGRY: { hull: STNGRY_HULL, flames: STNGRY_FLAMES },
  CROWN: { hull: CROWN_HULL, flames: CROWN_FLAMES },
  NR77: { hull: NR77_HULL, flames: NR77_FLAMES },
  BERTH4: { hull: BERTH4_HULL, flames: BERTH4_FLAMES },
  "QUR-I": { hull: QURI_HULL, flames: QURI_FLAMES },
  ZZ11: { hull: ZZ11_HULL, flames: ZZ11_FLAMES },
  WEGE: { hull: WEGE_HULL, flames: WEGE_FLAMES },
};

// Fragment cache for destruction animation
const fragmentCache: Record<string, HTMLImageElement[]> = {};

/**
 * Parse a ship's hull SVG into individual Colour_x5F_* fragment images
 * for the "blown to bits" destruction animation.
 * Excludes Stroke and Flames layers.
 */
export function getShipFragments(
  name: string,
  skinColours?: SkinColourMap,
  skinId?: string
): HTMLImageElement[] {
  const cacheKey = `frag_${name}_${skinId || "def"}`;
  if (fragmentCache[cacheKey]) return fragmentCache[cacheKey];

  const data = SHIP_ASSETS[name] || SHIP_ASSETS["AX15"];
  let hull = data.hull;
  if (skinColours) {
    hull = applySkinToSVG(hull, skinColours);
  }

  // Parse hull SVG to extract individual colour layer elements
  const parser = new DOMParser();
  const doc = parser.parseFromString(hull, "image/svg+xml");
  const fragments: HTMLImageElement[] = [];

  // Find all elements with Colour_x5F_* IDs (skip Stroke groups)
  const allElements = doc.querySelectorAll("[id]");
  const colourElements: Element[] = [];

  allElements.forEach((el) => {
    const id = el.getAttribute("id") || "";
    if (id.startsWith("Colour_x5F_") && !id.includes("Stroke")) {
      // Only take top-level colour elements (not nested ones already included in a parent group)
      let isNested = false;
      let parent = el.parentElement;
      while (parent) {
        const parentId = parent.getAttribute("id") || "";
        if (parentId.startsWith("Colour_x5F_")) {
          isNested = true;
          break;
        }
        parent = parent.parentElement;
      }
      if (!isNested) {
        colourElements.push(el);
      }
    }
  });

  // Wrap each element in its own SVG
  for (const el of colourElements) {
    const svgWrap = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 250 250">${el.outerHTML}</svg>`;
    fragments.push(createImageFromSVG(svgWrap));
  }

  // If no fragments found, create one from the whole hull as fallback
  if (fragments.length === 0) {
    fragments.push(createImageFromSVG(hull));
  }

  fragmentCache[cacheKey] = fragments;
  return fragments;
}

// Pre-created Image cache — key includes skin ID for skinned variants
const imageCache: Record<string, { hull: HTMLImageElement; flames: HTMLImageElement }> = {};

function createImageFromSVG(svg: string): HTMLImageElement {
  const img = new Image();
  img.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
  return img;
}

export function getShipImages(
  name: string,
  skinColours?: SkinColourMap,
  skinId?: string,
  jetSkinColours?: SkinColourMap,
  jetSkinId?: string
): { hull: HTMLImageElement; flames: HTMLImageElement } {
  const cacheKey = `${name}_${skinId || "def"}_${jetSkinId || "def"}`;
  if (imageCache[cacheKey]) return imageCache[cacheKey];

  const data = SHIP_ASSETS[name] || SHIP_ASSETS["AX15"];
  let hull = data.hull;
  let flames = data.flames;

  // Apply ship skin to hull (and flames if no separate jet skin)
  if (skinColours) {
    hull = applySkinToSVG(hull, skinColours);
    if (!jetSkinColours) {
      flames = applySkinToSVG(flames, skinColours);
    }
  }

  // Apply jet skin to flames if provided
  if (jetSkinColours) {
    flames = applySkinToSVG(flames, jetSkinColours);
  }

  const entry = {
    hull: createImageFromSVG(hull),
    flames: createImageFromSVG(flames),
  };
  imageCache[cacheKey] = entry;
  return entry;
}

// For Hangar/Store SVG inline rendering — returns raw hull and flames SVG inner content
export function getShipSVGData(name: string): ShipSVGData {
  return SHIP_ASSETS[name] || SHIP_ASSETS["AX15"];
}

export const AVAILABLE_SHIP_NAMES = Object.keys(SHIP_ASSETS);
